#!/usr/bin/env python3
"""
detect_input.py — 自动识别用户输入的数据源类型（仅文本和本地文件）。

用法：
    from detect_input import detect_data_source
    src = detect_data_source(user_input_text)
    # src = {"type": "local_file"|"local_data"|"keyword_only", "value": ...}
"""
import json
import os
import re
from typing import Dict, Optional


FILE_EXT_PATTERN = re.compile(r'([A-Za-z0-9_\-./\u4e00-\u9fa5]+?\.(?:log|xlsx|xls|json|csv|txt))', re.IGNORECASE)
JSON_BLOB = re.compile(r'\{[^{}]*"(test_name|results|product|scenario|threads|tps|qps)"[^{}]*\}', re.DOTALL)


def detect_data_source(text: str) -> Dict[str, Optional[str]]:
    """根据用户输入文本判定数据源类型。只支持本地文件和粘贴数据。"""
    if not text:
        return {"type": "keyword_only", "value": None}

    # 1) 本地文件路径
    file_matches = FILE_EXT_PATTERN.findall(text)
    cwd = os.getcwd()
    existing = []
    for fp in file_matches:
        for base in (None, cwd):
            cand = fp if base is None else os.path.join(base, fp)
            if os.path.exists(cand):
                existing.append(os.path.abspath(cand))
                break
    if existing:
        return {
            "type": "local_file",
            "value": existing[0],
            "extras": existing[1:] if len(existing) > 1 else [],
        }

    # 2) 内嵌 JSON 数据（用户直接粘贴）
    json_match = JSON_BLOB.search(text)
    if json_match:
        start = json_match.start()
        depth = 0
        end = start
        for i, ch in enumerate(text[start:], start=start):
            if ch == '{':
                depth += 1
            elif ch == '}':
                depth -= 1
                if depth == 0:
                    end = i + 1
                    break
        blob = text[start:end]
        try:
            json.loads(blob)
            return {"type": "local_data", "value": blob}
        except json.JSONDecodeError:
            pass

    # 3) 默认关键词
    return {"type": "keyword_only", "value": None}


def main():
    import argparse
    ap = argparse.ArgumentParser()
    ap.add_argument('--text', required=True, help='用户输入文本')
    args = ap.parse_args()
    result = detect_data_source(args.text)
    print(json.dumps(result, ensure_ascii=False, indent=2))


if __name__ == '__main__':
    main()

#!/usr/bin/env python3
"""
parse_intent.py — 用户自然语言 → intent.json（仅支持文本和文件输入）

规则驱动，无 LLM 依赖。
"""
import argparse
import json
import os
import re
import sys
from typing import Any, Dict, List, Optional

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from detect_input import detect_data_source  # noqa: E402

# ============== 中英映射表 ==============
SCENARIO_MAP = {
    '只读': 'read_only',
    '只写': 'write_only',
    '写入': 'write_only',
    '读写': 'read_write',
    '混合读写': 'read_write',
    '更新索引': 'update_index',
    '更新非索引': 'update_non_index',
    '点查': 'point_select',
    '点选': 'point_select',
    '主键点查': 'point_select',
    '随机点查': 'random_points',
    '随机范围查询': 'random_ranges',
}

ARCH_MAP = {
    '集中式': '集中式性能',
    '分布式': '分布式性能',
    '单机': '集中式性能',
    '集群': '分布式性能',
}

TOOL_MAP = {
    'sysbench': 'sysbench',
    'benchmarksql': 'BenchmarkSQL',
    'tpcc': 'BenchmarkSQL',
    'tpch': 'tpch',
}

# ============== report_type 识别 ==============
RE_COMPARISON = re.compile(r'对比|比较|差异|哪个更好|\bvs\b', re.IGNORECASE)
RE_ITERATION = re.compile(r'迭代|版本演进|历史趋势|变化趋势|演进')
RE_CUSTOM = re.compile(r'客制化|专项|定制|深度分析|详细分析')


def detect_report_type(text: str) -> str:
    if RE_COMPARISON.search(text):
        return 'comparison'
    if RE_ITERATION.search(text):
        return 'iteration'
    if RE_CUSTOM.search(text):
        return 'custom'
    return 'single'


# ============== OR vs AND 识别 ==============
RE_OR_SEPARATOR = re.compile(r'\s*[和或、]\s*|以及')


def extract_test_name_keywords(text: str) -> Dict[str, Any]:
    arch_hits = {kw: ARCH_MAP[kw] for kw in ARCH_MAP if kw in text}
    scen_hits = {kw: SCENARIO_MAP[kw] for kw in SCENARIO_MAP if kw in text}

    if not arch_hits and not scen_hits:
        return {'test_name_keywords': [], 'test_name_keywords_or': None}

    has_separator = bool(RE_OR_SEPARATOR.search(text))
    distinct_scenarios = list(set(scen_hits.values()))

    if has_separator and len(distinct_scenarios) >= 2:
        arch_part = list(set(arch_hits.values()))
        groups = [arch_part + [scen] for scen in distinct_scenarios]
        return {
            'test_name_keywords': None,
            'test_name_keywords_or': groups,
        }

    keywords = list(set(arch_hits.values()) | set(scen_hits.values()))
    return {
        'test_name_keywords': keywords,
        'test_name_keywords_or': None,
    }


# ============== 版本号 ==============
RE_VERSION = re.compile(r'(\d+\.\d+\.\d+(?:[\.\-]\w+)?)')


def extract_versions(text: str) -> List[str]:
    return list(dict.fromkeys(RE_VERSION.findall(text)))


# ============== 数值参数 ==============
RE_THREADS = re.compile(r'(\d+)\s*(?:threads|线程|并发)')
RE_TABLES = re.compile(r'(\d+)\s*(?:tables|表|张表)')
RE_TIME = re.compile(r'(?:time|测试时长|测试时间)[\s=为:]*(\d+)')
RE_WAREHOUSES = re.compile(r'(\d+)\s*(?:warehouses|仓库)')


def extract_results_filters(text: str) -> Dict[str, Optional[str]]:
    out = {'threads': None, 'tables': None, 'table_size': None, 'time': None, 'warehouses': None}
    if m := RE_THREADS.search(text):
        out['threads'] = m.group(1)
    if m := RE_TABLES.search(text):
        out['tables'] = m.group(1)
    if m := RE_TIME.search(text):
        out['time'] = m.group(1)
    if m := RE_WAREHOUSES.search(text):
        out['warehouses'] = m.group(1)
    return out


def extract_tool_name(text: str) -> Optional[str]:
    lower = text.lower()
    for kw, val in TOOL_MAP.items():
        if kw.lower() in lower:
            return val
    return None


# ============== 主流程 ==============
def parse_intent(user_input: str) -> Dict[str, Any]:
    ds = detect_data_source(user_input)
    report_type = detect_report_type(user_input)
    test_name = extract_test_name_keywords(user_input)
    results_filters = extract_results_filters(user_input)
    versions = extract_versions(user_input)
    tool_name = extract_tool_name(user_input)

    intent = {
        'data_source_type': ds['type'],
        'data_source_value': ds.get('value'),
        'report_type': report_type,
        'dimension_filters': {
            **test_name,
            'tool_name': tool_name,
            'tool_version_keywords': versions,
            'component_name': None,
            'component_version': None,
        },
        'results_key_filters': results_filters,
        'task_filters': {'task_id': None, 'plan_id': None, 'report_id': None},
        'iteration_config': None,
        'custom_config': None,
        'other_info': None,
    }

    if report_type == 'iteration':
        intent['iteration_config'] = {
            'version_range': versions,
            'regression_threshold_pct': 5,
        }
    if report_type == 'custom':
        focus = None
        if 'buffer' in user_input.lower() or 'pool' in user_input.lower():
            focus = 'buffer_pool'
        elif 'numa' in user_input.lower():
            focus = 'numa'
        elif '高并发' in user_input:
            focus = '高并发'
        elif '表数量' in user_input:
            focus = '表数量'
        intent['custom_config'] = {
            'focus_dimension': focus,
            'extra_questions': [user_input.strip()] if focus else [],
        }

    return intent


def main():
    ap = argparse.ArgumentParser(description='用户输入 → intent.json')
    ap.add_argument('--text', required=True, help='用户输入')
    ap.add_argument('--out', required=True, help='intent.json 输出路径')
    args = ap.parse_args()

    intent = parse_intent(args.text)
    os.makedirs(os.path.dirname(args.out) or '.', exist_ok=True)
    with open(args.out, 'w', encoding='utf-8') as f:
        json.dump(intent, f, ensure_ascii=False, indent=2)
    print(f'intent.json 已生成: {args.out}')
    print(json.dumps(intent, ensure_ascii=False, indent=2))


if __name__ == '__main__':
    main()

#!/usr/bin/env python3
"""
data_source_adapter.py — 统一数据接入（仅支持本地文件和粘贴数据）

适配器：
  - local_file: 本地 .log/.xlsx/.json/.csv
  - local_data: 粘贴的 JSON 文本
  - keyword_only: 仅关键词（将回退为提示用户提供文件）

标准结构：
{
  "meta": {"products": [...], "scenarios": [...], "concurrencies": [...], ...},
  "records": [{"product": ..., "scenario": ..., "threads": ..., "tps": ..., "qps": ..., "p95_ms": ...}, ...]
}
"""
import argparse
import csv
import json
import os
import re
import sys
from collections import defaultdict
from typing import Any, Dict, List, Optional

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from log_parser import parse_log  # noqa: E402


# ============== 反向场景映射 ==============
SCEN_FROM_DB = {
    'point_select': 'oltp_point_select',
    'read_only': 'oltp_read_only',
    'write_only': 'oltp_write_only',
    'read_write': 'oltp_read_write',
    'update_index': 'oltp_update_index',
    'update_non_index': 'oltp_update_non_index',
    'random_points': 'oltp_random_points',
    'random_ranges': 'oltp_random_ranges',
    'tpmC': 'tpmC',
}


def _normalize_scenario(name: str) -> Optional[str]:
    """从 test_name 字符串中识别 sysbench 标准场景名。"""
    if not name:
        return None
    m = re.search(r'(oltp_[a-z_]+)', name, re.IGNORECASE)
    if m:
        return m.group(1).lower()
    for short, full in SCEN_FROM_DB.items():
        if short in name:
            return full
    return None


def _extract_threads(test_name: str, results_key: str) -> Optional[int]:
    m = re.search(r'(\d+)\s*threads?', test_name or '', re.IGNORECASE)
    if m:
        return int(m.group(1))
    m = re.search(r'threads\s*=\s*(\d+)', results_key or '', re.IGNORECASE)
    if m:
        return int(m.group(1))
    return None


# ============== 适配器：本地 log ==============
def adapter_local_log(path: str) -> Dict[str, Any]:
    header, records_raw = parse_log(path)
    product = header.get('engine', os.path.basename(path).split('.')[0])
    records = []
    for r in records_raw:
        scenario = r['scenario']
        if not scenario.startswith('oltp_'):
            scenario = 'oltp_' + scenario.replace('oltp_', '').lstrip('_')
        records.append({
            'product': product,
            'scenario': scenario,
            'threads': r['threads'],
            'tps': r['tps'],
            'qps': r['qps'],
            'p95_ms': r.get('p95_ms'),
            'p99_ms': r.get('p99_ms'),
            'source_log': os.path.basename(path),
        })

    if not records:
        raise RuntimeError(f'日志文件未解析到有效数据: {path}')

    return {
        'meta': {
            'products': [product],
            'scenarios': sorted({r['scenario'] for r in records}),
            'concurrencies': sorted({r['threads'] for r in records}),
            'test_env': {},
            'log_meta': [{
                'product': product,
                'log_file': os.path.basename(path),
                'engine': header['engine'],
                'start_time': header['start_time'],
                'db_endpoint': header['db_endpoint'],
                'data_config': header['data_config'],
                'duration_sec': header['duration_sec'],
            }],
            'source_info': {'type': 'local_file', 'value': path, 'rows_fetched': len(records)},
        },
        'records': records,
    }


# ============== 适配器：本地 xlsx ==============
def adapter_local_xlsx(path: str) -> Dict[str, Any]:
    import openpyxl
    wb = openpyxl.load_workbook(path, data_only=True)
    product_sheets = [s for s in wb.sheetnames if not s.startswith('_')]
    expected = ['scenario', 'threads', 'tps', 'qps', 'p95_ms', 'p99_ms']
    records = []
    products = []
    for sn in product_sheets:
        ws = wb[sn]
        header = [c.value for c in ws[1]]
        if header[:6] != expected:
            raise RuntimeError(f'{sn} 表头不符合标准: {header}')
        products.append(sn)
        for row in ws.iter_rows(min_row=2, values_only=True):
            if not row or row[0] is None:
                continue
            records.append({
                'product': sn,
                'scenario': row[0],
                'threads': row[1],
                'tps': row[2],
                'qps': row[3],
                'p95_ms': row[4],
                'p99_ms': row[5] if len(row) > 5 else None,
                'source_log': os.path.basename(path),
            })
    return {
        'meta': {
            'products': products,
            'scenarios': sorted({r['scenario'] for r in records}),
            'concurrencies': sorted({r['threads'] for r in records}),
            'test_env': {},
            'log_meta': [{'product': p, 'log_file': os.path.basename(path)} for p in products],
            'source_info': {'type': 'local_file', 'value': path, 'rows_fetched': len(records)},
        },
        'records': records,
    }


# ============== 适配器：本地 json ==============
def adapter_local_json(path: str) -> Dict[str, Any]:
    with open(path, encoding='utf-8') as f:
        data = json.load(f)
    if isinstance(data, dict) and 'records' in data and 'meta' in data:
        return data  # 已是标准格式
    if isinstance(data, list):
        # 列表格式：适配为 records
        return adapter_local_rows(data, source_value=path)
    raise RuntimeError(f'JSON 格式不识别: {path}')


# ============== 适配器：本地 csv ==============
def adapter_local_csv(path: str) -> Dict[str, Any]:
    records = []
    with open(path, encoding='utf-8-sig') as f:
        reader = csv.DictReader(f)
        for row in reader:
            records.append({
                'product': row.get('product', os.path.basename(path)),
                'scenario': row['scenario'],
                'threads': int(row['threads']),
                'tps': float(row['tps']),
                'qps': float(row['qps']),
                'p95_ms': float(row['p95_ms']) if row.get('p95_ms') else None,
                'p99_ms': float(row['p99_ms']) if row.get('p99_ms') else None,
            })
    return {
        'meta': {
            'products': sorted({r['product'] for r in records}),
            'scenarios': sorted({r['scenario'] for r in records}),
            'concurrencies': sorted({r['threads'] for r in records}),
            'test_env': {},
            'log_meta': [],
            'source_info': {'type': 'local_file', 'value': path, 'rows_fetched': len(records)},
        },
        'records': records,
    }


# ============== 适配器：本地 JSON 列表数据 ==============
def adapter_local_rows(rows: List[Dict[str, Any]], source_value: str = '') -> Dict[str, Any]:
    """将通用 JSON 行列表转换为标准 records 结构。"""
    records = []
    for row in rows:
        scenario = row.get('scenario', '') or row.get('test_name', '')
        if not scenario or not scenario.startswith('oltp_'):
            # 尝试从 test_name 中提取
            dim = row.get('dimension', {})
            if isinstance(dim, str):
                try:
                    dim = json.loads(dim)
                except Exception:
                    dim = {}
            test_name = dim.get('test_name', '') or row.get('test_name', '')
            scenario = _normalize_scenario(test_name) or scenario

        threads = row.get('threads') or _extract_threads(
            row.get('test_name', '') or (row.get('dimension', {}).get('test_name', '')
                                         if isinstance(row.get('dimension', {}), dict) else ''),
            row.get('results_key', ''),
        )

        tps = _to_float(row.get('tps') or row.get('TPS'))
        qps = _to_float(row.get('qps') or row.get('QPS'))
        results = row.get('results', {})
        if isinstance(results, str):
            try:
                results = json.loads(results)
            except Exception:
                results = {}
        p95 = _to_float(row.get('p95_ms') or results.get('p95') or results.get('p95_latency'))
        p99 = _to_float(row.get('p99_ms') or results.get('p99') or results.get('p99_latency'))

        if not scenario or threads is None:
            continue
        if tps is None and qps is None:
            continue
        qps = qps or tps
        tps = tps or qps

        product = row.get('product', source_value or 'test-product')
        records.append({
            'product': product,
            'scenario': scenario,
            'threads': threads,
            'tps': tps,
            'qps': qps,
            'p95_ms': p95,
            'p99_ms': p99,
        })

    if not records:
        raise RuntimeError(f'未能从数据中解析出有效记录: {source_value}')

    return {
        'meta': {
            'products': sorted({r['product'] for r in records}),
            'scenarios': sorted({r['scenario'] for r in records}),
            'concurrencies': sorted({r['threads'] for r in records}),
            'test_env': {},
            'log_meta': [],
            'source_info': {'type': 'local_data', 'value': source_value, 'rows_fetched': len(records)},
        },
        'records': records,
    }


def _to_float(v):
    if v is None:
        return None
    try:
        return float(v)
    except (TypeError, ValueError):
        return None


# ============== 主分发 ==============
def load_records(intent: Dict[str, Any]) -> Dict[str, Any]:
    ds_type = intent['data_source_type']
    ds_value = intent.get('data_source_value')

    if ds_type == 'local_file':
        if not ds_value or not os.path.exists(ds_value):
            raise RuntimeError(f'本地文件不存在: {ds_value}')
        ext = ds_value.rsplit('.', 1)[-1].lower()
        if ext == 'log':
            return adapter_local_log(ds_value)
        if ext in ('xlsx', 'xls'):
            return adapter_local_xlsx(ds_value)
        if ext == 'json':
            return adapter_local_json(ds_value)
        if ext == 'csv':
            return adapter_local_csv(ds_value)
        raise RuntimeError(f'不识别的扩展名: {ext}')

    if ds_type == 'local_data':
        data = json.loads(ds_value)
        rows = data if isinstance(data, list) else [data]
        return adapter_local_rows(rows, source_value='local_data')

    if ds_type == 'keyword_only':
        raise RuntimeError(
            '未检测到具体的数据文件。'
            '请提供以下格式之一：\n'
            '  - sysbench .log 日志文件路径\n'
            '  - .xlsx Excel 文件路径\n'
            '  - .json 数据文件路径\n'
            '  - .csv 数据文件路径\n'
            '  - 直接粘贴 JSON 数据'
        )

    raise RuntimeError(f'未知 data_source_type: {ds_type}')


# ============== 数据质量门控 ==============
def quality_check(extracted: Dict[str, Any]) -> Dict[str, Any]:
    records = extracted['records']
    n = len(records)
    if n == 0:
        raise RuntimeError('records 为空')

    null_tps = sum(1 for r in records if r.get('tps') is None)
    null_qps = sum(1 for r in records if r.get('qps') is None)
    null_p95 = sum(1 for r in records if r.get('p95_ms') is None)
    null_p99 = sum(1 for r in records if r.get('p99_ms') is None)

    if null_tps or null_qps or null_p95:
        raise RuntimeError(
            f'数据空值率超标 — TPS={null_tps}/{n}, QPS={null_qps}/{n}, P95={null_p95}/{n}'
        )

    cbm = defaultdict(lambda: defaultdict(set))
    for r in records:
        cbm[r['product']][r['scenario']].add(r['threads'])

    return {
        'records': n,
        'tps_null_rate': null_tps / n,
        'qps_null_rate': null_qps / n,
        'p95_null_rate': null_p95 / n,
        'p99_null_rate': null_p99 / n,
        'concurrencies_by_product_scenario': {
            p: {s: sorted(ts) for s, ts in sd.items()} for p, sd in cbm.items()
        },
    }


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--intent', required=True)
    ap.add_argument('--out', required=True)
    args = ap.parse_args()

    with open(args.intent, encoding='utf-8') as f:
        intent = json.load(f)

    extracted = load_records(intent)
    qc = quality_check(extracted)
    extracted['meta']['concurrencies_by_product_scenario'] = qc['concurrencies_by_product_scenario']

    os.makedirs(os.path.dirname(args.out) or '.', exist_ok=True)
    with open(args.out, 'w', encoding='utf-8') as f:
        json.dump(extracted, f, ensure_ascii=False, indent=2, default=str)
    print(f'extracted_data.json 已保存: {args.out}（{qc["records"]} 条记录）')
    print(f'   产品: {extracted["meta"]["products"]}')
    print(f'   场景: {extracted["meta"]["scenarios"][:10]}{"..." if len(extracted["meta"]["scenarios"])>10 else ""}')
    print(f'   并发档: {extracted["meta"]["concurrencies"]}')


if __name__ == '__main__':
    main()

#!/usr/bin/env python3
"""
run_pipeline.py — 一键端到端执行（自包含版本）

输入：用户自然语言（--text）或已生成的 intent.json（--intent）
输出：output/{report.md, report.docx, report.html, charts/, data/}

用法：
    # 模式 1：自然语言
    python run_pipeline.py --text "对 test.log 生成单次测试报告" --out output

    # 模式 2：本地文件
    python run_pipeline.py --text "/path/to/sysbench.log" --out output

    # 模式 3：已有 intent.json
    python run_pipeline.py --intent data/intent.json --out output
"""
import argparse
import json
import os
import subprocess
import sys
from pathlib import Path

HERE = Path(__file__).parent
SKILL_DIR = HERE.parent


def run(cmd, cwd=None):
    print(f'\n> {" ".join(cmd)}')
    effective_cwd = cwd or os.getcwd()
    r = subprocess.run(cmd, cwd=effective_cwd)
    if r.returncode != 0:
        raise SystemExit(f'步骤失败: {" ".join(cmd)}')


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--text', help='用户自然语言输入')
    ap.add_argument('--intent', help='已有 intent.json 路径（跳过解析）')
    ap.add_argument('--out', required=True, help='输出目录')
    args = ap.parse_args()

    out_dir = Path(args.out).resolve()
    data_dir = out_dir / 'data'
    charts_dir = out_dir / 'charts'
    out_dir.mkdir(parents=True, exist_ok=True)
    data_dir.mkdir(exist_ok=True)
    charts_dir.mkdir(exist_ok=True)

    intent_path = data_dir / 'intent.json'
    extracted_path = data_dir / 'extracted_data.json'
    analysis_path = data_dir / 'analysis_results.json'
    insights_path = data_dir / 'insights.json'

    # === 阶段 1：意图解析 ===
    if args.intent:
        with open(args.intent, encoding='utf-8') as f:
            intent = json.load(f)
        with open(intent_path, 'w', encoding='utf-8') as f:
            json.dump(intent, f, ensure_ascii=False, indent=2)
    else:
        if not args.text:
            raise SystemExit('必须提供 --text 或 --intent')
        run([sys.executable, str(HERE / 'parse_intent.py'),
             '--text', args.text, '--out', str(intent_path)])

    intent = json.load(open(intent_path, encoding='utf-8'))
    print(f'\n意图解析结果：')
    print(f'  data_source_type: {intent["data_source_type"]}')
    print(f'  report_type:      {intent["report_type"]}')

    # === 阶段 2：数据接入 ===
    run([sys.executable, str(HERE / 'data_source_adapter.py'),
         '--intent', str(intent_path),
         '--out', str(extracted_path)])

    # === 阶段 3：分析 ===
    run([sys.executable, str(HERE / 'analyze.py'),
         '--extracted', str(extracted_path),
         '--intent', str(intent_path),
         '--out-analysis', str(analysis_path),
         '--out-insights', str(insights_path)])

    # === 阶段 4：图表 ===
    run([sys.executable, str(HERE / 'generate_charts.py'),
         '--extracted', str(extracted_path),
         '--analysis', str(analysis_path),
         '--charts-dir', str(charts_dir),
         '--report-type', intent['report_type']])

    # === 阶段 5：渲染三格式 ===
    run([sys.executable, str(HERE / 'render_all.py'),
         '--extracted', str(extracted_path),
         '--analysis', str(analysis_path),
         '--insights', str(insights_path),
         '--intent', str(intent_path),
         '--out-dir', str(out_dir),
         '--charts-dir-rel', 'charts'])

    print('\n流水线完成')
    print(f'   报告位于: {out_dir}/')
    print(f'     - report.md')
    print(f'     - report.docx')
    print(f'     - report.html')
    print(f'     - charts/  ({len(list(charts_dir.glob("*.png")))} 张图)')
    print(f'     - data/    ({len(list(data_dir.glob("*.*")))} 份中间产物)')


if __name__ == '__main__':
    main()
